    if (wantResult && _ddRowResult(hist, f.date) !== wantResult) continue;
    // NUMERATOR AND DENOMINATOR OVER THE SAME FIGHTS, ALWAYS. A row we cannot time
    // is dropped from BOTH the count and the clock rather than counted against a
    // clock that never ran — that would inflate the rate silently, which is the
    // failure mode that does not announce itself. No estimation either: guessing the
    // missing fight's length is inventing data to protect a total.
    // MEASURED COST of that strictness across the card: 2 rows of 927, 1 takedown
    // (Robert Valentin 1 -> 0). Perez keeps all 15; his one untimed bout had none.
    const dur = _ddRowSecs(hist, f.date);
    if (dur == null) continue;
