// GRADING ONE MAN AGAINST HIS DIVISION — and the same discipline as _mhLeadProp,
// because I got this wrong the same way twice in one feature.
//
// The first cut was `r < median ? 'good' : 'bad'`, which painted Usman RED for
// allowing 31% at range against a welterweight median of 31%. Dead average, marked
// down. Every fighter is on one side of a median, so a bare comparison colours the
// entire card and says nothing — it's the "49% vs 50% is green" bug wearing the
// other team's kit.
//
// A grade needs the gap to clear TWO bars, and they answer different questions:
//   * >= one division spread  — is he actually unusual FOR HIS DIVISION? (the
//     medians ship with a robust IQR-based spread precisely so this is askable)
//   * >= 2 standard errors    — is his own rate real, or 25 attempts of noise?
// Fail either and the row is neutral, which is the truthful answer for the many
// fighters who are simply normal.
//
// `lowerIsBetter` for rows where the number is a beating.
function _mhGrade(r, n, norm, lowerIsBetter){
  if (!norm || !n) return null;
  const gap = Math.abs(r - norm.med);
  const se = Math.sqrt(Math.max(r * (1 - r), 0.01) / n);
  if (gap < norm.spread || gap < 2 * se) return 'n';
  const better = lowerIsBetter ? (r < norm.med) : (r > norm.med);
  return better ? 'w' : 'b';
}

function _mhLeadRatio(a, b, min){
  // For magnitudes that aren't counts of trials and have no n to test against —
  // control time in seconds. A stated, visible rule: one side has to be at least a
  // quarter as much again. 50 minutes against 16 clears it; 50 against 45 doesn't.
  //
  // PASS IT PER-FIGHT SECONDS, NOT CAREER SECONDS. This test has no exposure term
  // at all — it cannot tell 50 minutes over 8 fights from 50 minutes over 30 — so
  // on career totals it would report every veteran as a controller. Poisson doesn't
  // apply here (seconds aren't a count of events), so exposure has to be divided
  // out by the CALLER before the ratio is taken. Both call sites do.
  const hi = Math.max(a, b), lo = Math.min(a, b);
  if (!hi || hi < (min || 1.25) * Math.max(lo, 1e-9)) return 0;
  return a > b ? 1 : 2;
}

// One comparison row: label centred, values outside, bars growing OUT from the
// middle so the longer side is the message and you get it before you read a digit.
// `lead` says who (if anyone) has earned the accent — see the tests above. Omit it
// for rows where bigger isn't better: how a man distributes his offense is a habit,
// not a virtue, and painting the bigger share green would be scoring it.
function mhCmp(label, a, b, opts){
  opts = opts || {};
  const pc = v => Math.max(0, Math.min(100, Math.round((v || 0) * 100)));
  // Bars are always neutral gray in the Deep Dive hub now, on both the Striking
  // and the Grappling tab — no green "leader" accent and no red "below his own
  // division's median" accent either. `opts.lead`/`opts.gradeL`/`opts.gradeR`
  // still arrive from every call site unchanged; they just no longer pick the
  // bar's colour.
  let ac = 'n', bc = 'n';
  // The norm as a tick. Context without printing a z-score at anybody: 91% of leg
  // kicks landing sounds alarming until you can see that 84% is normal.
  //
  // PER SIDE, because the two men can be in different divisions (a fighter moving
  // up, a catchweight) and each tick has to mark HIS peers. `norm` sets both.
  const nL = opts.normL != null ? opts.normL : opts.norm;
  const nR = opts.normR != null ? opts.normR : opts.norm;
  const tick = side => {
    const v = side === 'l' ? nL : nR;
    return v == null ? '' : '<u style="' + (side === 'l' ? 'right:' : 'left:') + pc(v) + '%"></u>';
  };
  const val = (o, right) => '<div class="mh-cmp-v' + (right ? ' r' : '') + '">' + o.txt +
    (o.sub ? '<i>' + o.sub + '</i>' : '') + '</div>';
  return '<div class="mh-cmp"><div class="mh-cmp-lbl">' + label + '</div>' +
    '<div class="mh-cmp-b">' + val(a, false) +
      '<div class="mh-bars">' +
        '<div class="mh-bar l"><span class="' + ac + '" style="width:' + pc(a.frac) + '%"></span>' + tick('l') + '</div>' +
        '<div class="mh-bar r"><span class="' + bc + '" style="width:' + pc(b.frac) + '%"></span>' + tick('r') + '</div>' +
      '</div>' + val(b, true) +
    '</div></div>';
}

// PER-CELL BASELINES, MEASURED FROM THE GRID FILE ITSELF.
//
// THE ABSOLUTE RATE IS NOT THE STORY, AND SHADING BY IT PUT THE MUSH BACK. The
// first version of this coloured each cell by its raw accuracy on a flat 0–100%
// scale, and both fighters came out near-identical walls of green — because
// head-at-range is ~35% for EVERYONE and leg kicks are ~82% for EVERYONE. The
// palette was encoding WHICH TARGET THE CELL WAS, not one thing about the man in
// it. Measured over the 109 fighters in the grid:
//     dist.head    n=105  mean 35.3%  sd 6.6   (spread 16–52%)
//     dist.leg     n= 57  mean 81.7%  sd 9.2   (spread 57–95%)
//     ground.head  n= 55  mean 69.5%  sd 10.2  (spread 39–88%)
// Between cells: 46 points. Within a cell, where the fighter actually lives: 7–10.
// A flat scale spends its whole range on the former and leaves nothing for the
// latter. So a cell is shaded against WHAT A TYPICAL FIGHTER ON THIS CARD DOES IN
// THAT CELL, which is the only comparison that says anything about this man.
//
// (The premise re-checked on today's file, since it is the reason the feature
// exists: corr(head-at-distance, head-on-ground) = -0.010 over the 55 fighters with
// both. Unrelated skills, still.)
//
// Computed here rather than shipped in grid-names.json because the grid is already
// in memory by the time the hub opens, this is exactly the population the footnote
// claims, and a baseline that travels in a second file is a baseline that can go
// stale against the one it describes.
// THE CARD-WIDE FALLBACK. Computed here from FIGHT_GRID, over whoever is on the
// card, for all three metrics. This is what every cell used to shade against, and
// it is now only reached when a fighter's DIVISION has too few peers to have a
// median of its own (see mhNorm). Post-sweep that should be rare; pre-sweep it is
// almost everything, which is why the legend names whichever one it used.
let _mhBase = null;
function mhCardBase(){
  if (_mhBase) return _mhBase;
  const G = window.FIGHT_GRID || {};
  const acc = Array.from({length:9}, () => []);
  const allow = Array.from({length:9}, () => []);
  const aim = Array.from({length:9}, () => []);
  for (const k of Object.keys(G)) {
    const off = Array.from({length:9}, () => [0,0]);
    const def = Array.from({length:9}, () => [0,0]);
    // Full record, matching _ddGrid and split-fight-grid.cjs. A fallback norm built
    // from 8-fight samples, judging fighters measured over whole careers, would be
    // the same statistic computed two ways and compared as if it were one.
    for (const r of (G[k]||[])) {
      if (!r) continue;
      if (r.f && r.f.g) for (let i=0;i<9;i++){ off[i][0] += r.f.g[i][0]; off[i][1] += r.f.g[i][1]; }
      if (r.o && r.o.g) for (let i=0;i<9;i++){ def[i][0] += r.o.g[i][0]; def[i][1] += r.o.g[i][1]; }
    }
    const tot = off.reduce((s,c) => s+c[1], 0);
    // The renderer's floor, applied to the norm too: a fighter joins a cell's
    // baseline only if he has enough attempts there for his own rate to mean
    // anything. Otherwise the norm is built out of the noise it exists to judge.
    for (let i=0;i<9;i++){
      if (off[i][1] >= _MH_FLOOR) acc[i].push(off[i][0]/off[i][1]);
      if (def[i][1] >= _MH_FLOOR) allow[i].push(def[i][0]/def[i][1]);
      if (tot >= 150) aim[i].push(off[i][1]/tot);
    }
  }
  const pack = v => {
    if (v.length < 8) return null;     // too few fighters to call anything normal
    const s = v.slice().sort((a,b) => a-b);
    const q = p => { const x = (s.length-1)*p, lo = Math.floor(x), hi = Math.ceil(x);
      return lo === hi ? s[lo] : s[lo] + (s[hi]-s[lo])*(x-lo); };
    const med = s.length % 2 ? s[(s.length-1)/2] : (s[s.length/2-1] + s[s.length/2])/2;
    // Median + IQR/1.349, matching split-fight-grid.cjs exactly so the two
    // baselines are the same statistic and a cell doesn't visibly jump when a
    // division crosses the peer floor and swaps from one to the other.
    return [med, Math.max((q(0.75)-q(0.25))/1.349, 0.01), v.length];
  };
  _mhBase = { acc: acc.map(pack), allow: allow.map(pack), aim: aim.map(pack) };
  return _mhBase;
}

// A FIGHTER'S DIVISION. Shipped in the manifest so the browser doesn't scan
// FIGHTERS (3,101 rows) on every panel open. Normalised lookup, because this is the
// join that has been written wrong four times in this codebase.
let _mhDivIdx = null;
function mhDivOf(name){
  const D = window.GRID_DIVS || {};
  if (D[name]) return D[name];
  if (!_mhDivIdx) _mhDivIdx = new Map(Object.keys(D).map(k => [_gridNorm(k), D[k]]));
  return _mhDivIdx.get(_gridNorm(name)) || null;
}

// THE BASELINE FOR ONE FIGHTER, ONE METRIC, ONE CELL.
//
// DIVISION MEDIAN FIRST, because "34% at range" is a different fact for a
// flyweight and a heavyweight, and because it's the comparison the fighter profile
// bars have always made (statDivMedians). Falls back to the card norm only when the
// man's division hasn't got 8 peers with data in that cell.
//
// BE CLEAR ABOUT WHAT THIS BUYS: measured across the 109-fighter card grid,
// division accounts for only 12–19% of the variance in these rates — between-
// division means spread 2.3–3.5 points while fighters WITHIN a division spread
// 6.3–8.4. It is the right comparison and it is not a large one. The honest gain
// is that a heavyweight stops being marked down for heavyweight output.
//
// Returns {med, spread, n, src} or null. `src` is carried so the legend can say
// which baseline the reader is actually looking at, rather than claiming "division"
// over a grid that's half card norm.
function mhNorm(name, metric, i){
  const DB = window.GRID_DIVBASE || {};
  const d = mhDivOf(name);
  const e = d && DB[d] && DB[d][metric] && DB[d][metric][i];
  if (e) return { med: e[0], spread: e[1] || 0.01, n: e[2], src: 'div', div: d };
  const c = mhCardBase()[metric];
  const b = c && c[i];
  return b ? { med: b[0], spread: b[1], n: b[2], src: 'card' } : null;
}

// THE GRID, ON SCREEN AT LAST. Dern is +55 points better on the ground than at
// range; a kickboxer is +11; "head 79%" said the same thing for both, because the
// backfill was summing the cross-tab into margins and throwing this away.
//
// TAKES THE NAME, because the baseline is now HIS DIVISION'S. Each man is shaded
// against his own peers — which for a normal bout is the same division for both,
// and for a catchweight or a fighter moving up is correctly not.
function mhGrid(G, which, name){
  const POS = [['dist','Distance'],['clinch','Clinch'],['ground','Ground']];
  const metric = which === 'cellsD' ? 'allow' : 'acc';
  // Lower is better when the number is what LANDS ON HIM. Without this the man
  // getting hit least in his division lights up red.
  const invert = which === 'cellsD';
  const srcs = new Set();
  let h = '<div class="mh-grid"><div></div>' +
    ['Head','Body','Leg'].map(t => '<div class="mh-gh">' + t + '</div>').join('');
  POS.forEach(([p, plabel]) => {
    h += '<div class="mh-gr">' + plabel + '</div>';
    ['head','body','leg'].forEach(t => {
      const i = _MH_GI(p,t);
      const c = G[which][i];
      // THREE STATES, NOT TWO. "—" used to cover both "nothing happened here" and
      // "something happened but not enough to rate", and 639 of 981 card cells are
      // below the floor — 254 genuinely empty, 385 with real but small samples, 164
      // of those in the 10–24 range. Rendering 16/17 identically to 0/0 throws away
      // the difference between no evidence and a little evidence.
      //
      // NOT shaded anyway, which was the other option: a 2/2 cell would come out
      // maximally green and be the loudest thing on the grid while being the least
      // real. The floor exists precisely to stop that. So the thin-but-present cells
      // get their OWN treatment — dashed, uncoloured, sample shown — and the legend
      // says what dashed means.
      const n = c[1];
      const empty = n === 0;
      const thin = n < _MH_FLOOR;
      const r = n ? c[0]/n : 0;
      const b = thin ? null : mhNorm(name, metric, i);
      let bg = 'rgba(255,255,255,0.03)';
      if (b) {
        srcs.add(b.src);
        // Capped at 2 spreads. Past that the colour stops meaning anything a reader
        // can use and starts being a competition between the loudest two cells.
        let z = Math.max(-1, Math.min(1, ((r - b.med) / b.spread) / 2));
        if (invert) z = -z;
        bg = z >= 0 ? 'rgba(0,230,104,' + (0.04 + 0.46*z).toFixed(3) + ')'
                    : 'rgba(255,64,64,' + (0.04 + 0.34*(-z)).toFixed(3) + ')';
      }
      const cls = empty ? ' empty' : (thin ? ' thin' : '');
      h += '<div class="mh-gc' + cls + '" style="background:' + bg + '">' +
        '<b>' + (thin ? (empty ? '·' : Math.round(r*100) + '%') : Math.round(r*100) + '%') + '</b>' +
        '<i>' + (empty ? '—' : c[0] + '/' + n) + '</i></div>';
      if (thin && !empty) srcs.add('thin');
    });
  });
  return { html: h + '</div>', srcs };
}

// NO WEIGHT-CLASS TAG OVER THE GRIDS.
//
// It used to print each fighter's roster division beside his name. Measured, that
// was redundant on 47 of the 50 bouts with a button — both men are in the same
// division — and on the other 3 it did more harm than good: it told a reader
// looking at a middleweight bout that Usman is a WELTERWEIGHT, which is true of his
// roster row and misleading about the fight in front of him. He is fighting at
// middleweight tonight.
//
// The baseline itself is unchanged and still each man's OWN division, which is the
// defensible choice: Usman's UFC record happened at welterweight, so his numbers
// ARE welterweight numbers and welterweight peers are the apples-to-apples
// comparison. Judging them against middleweight norms would compare his welterweight
// output to a division he has never fought in.
//
// THE COST, STATED: on those 3 bouts the two grids are shaded against different
// yardsticks with nothing on screen saying so. It is the honest baseline and the
// invisible one. If that trade ever looks wrong, the fix is to shade both men
// against the BOUT's weight class (already available as _mhState.meta.wc), not to
// put the tag back.

// Says which baseline the grid ACTUALLY used, rather than claiming "division" over
// a grid that is half card norm. Pre-sweep most divisions are under the peer floor,
// so this will read "card"; the sentence changes itself as the data fills in.
function mhBaseLabel(srcs){
  const div = srcs.has('div'), card = srcs.has('card');
  // Short, because it sits under the gradient. It still has to distinguish the
  // three cases: claiming "division" over a grid that is actually half card norm
  // would be a caption that lies, and the fallback is exactly the situation nobody
  // would think to check.
  if (div && card) return 'vs the division median (card median where a division is thin)';
  if (div) return 'vs the division median';
  if (card) return 'vs the card median — no division here has enough fighters yet';
  return '';
}

// THE READ, OR AN HONEST ADMISSION THAT THERE ISN'T ONE.
//
// The empty state is the feature, not a gap: 10 of 50 bouts have nothing to lead
// with on either tab, which is correct — most fights are not lopsided, and a panel
// that always has a verdict will invent one.
//
// ONE FUNCTION FOR BOTH TABS so the two can't drift apart. Each tab asks about its
// own domain, and when its domain is quiet it checks THE OTHER ONE before shrugging
// — a reader who lands on Striking in a fight that's decided on the mat should be
// pointed at the mat, not told there's nothing here.
function mhReadBlock(A, B, n1, n2, domain){
  const read = ddRead(A, B, n1, n2, domain);
  if (read) return '<div class="mh-read">' + read + '</div>';
  const other = domain === 'strike' ? 'grap' : 'strike';
  const otherName = domain === 'strike' ? 'Grappling' : 'Striking';
  const elsewhere = ddRead(A, B, n1, n2, other);
  const txt = 'No clear edge on paper' + (elsewhere ? '; see ' + otherName + '.' : '.');
  // The empty state still drops the green tint — with no read, there is nothing to
  // highlight. (It used to also recolour the left border; that border is gone, so
  // the override went with it rather than sitting here doing nothing.)
  return '<div class="mh-read" style="background:rgba(255,255,255,0.025);color:var(--muted)">' +
    txt + '</div>';
}

// THERE IS NO OVERVIEW TAB, AND REMOVING IT COST ALMOST NOTHING.
//
// Its grappling half was a byte-for-byte duplicate of the Grappling tab. Its
// striking half — strikes landed, strike accuracy, what-lands-on-him — was the
// AGGREGATE of the very cross-tab the Striking tab breaks out cell by cell, i.e.
// the summed-into-one-number view this whole feature exists to replace. A landing
// tab whose job was to average away the thing the next tab shows you properly.
//
// Only ONE number on it was not available anywhere else: knockdowns, which aren't
// in the grid at all. It now sits at the foot of "Where his offense goes". The two
// headline totals it also carried — strikes landed, strike accuracy — are gone
// outright: both are just the grid's nine cells added back up, which is the
// averaging this feature exists to undo, and the grid is directly below them.
function mhStriking(A, B, n1, n2){
  // With Overview gone this is the landing tab, so when the striking is level the
  // read points at the mat instead of shrugging — see mhReadBlock.
  let h = mhReadBlock(A, B, n1, n2, 'strike');

  // SIGNIFICANT STRIKES, LANDED AND ABSORBED — the one pair of numbers every other
  // section on this tab breaks apart by position and target. Opens the tab the same
  // way "Takedowns landed" opens the grappling one: accuracy leads the bar (a raw
  // volume number says nothing about whether it connects), a rate rides in the sub.
  // That's the point of doing it this way rather than printing the fighter's static
  // profile SLpM/SApM — those never move with the All/Wins/Losses filter, and this
  // does, because it's summed from the same cells/cellsD the rest of the tab reads.
  //
  // PER MINUTE, NOT PER 15 — every other rate on this panel (takedowns, control,
  // knockdowns) is per-15-min because those are rare events and a small number reads
  // oddly at 1-minute scale. Strikes are the opposite: they are the one count on this
  // whole panel that's naturally frequent, and per-15 stretches that into numbers like
  // "83.8/15min" that look broken next to "2.1/15min" for takedowns two sections down
  // — even though the arithmetic is correct (83.8/15 = 5.59, which is this exact
  // fighter's own profile SLpM). Per-minute is also the number a UFC fan already
  // knows as SLpM/SApM, so the sub reads as familiar instead of alarming.
  //
  // Exposure comes from `gridCage`, NOT `cage`/`_mhExpOf` — those read the FIGHT_STATS
  // loop a few hundred lines up, a different set of rows than `cells` below (grid
  // coverage and stats coverage are two independent backfills — see the comment on
  // gridCage in _ddGrid). Numerator and clock have to be the same fights.
  const mExp = G => (G && G.gridCage > 0) ? G.gridCage / 60 : 0;
  const perMinOK = mExp(A) > 0 && mExp(B) > 0;
  const mA = perMinOK ? mExp(A) : 0, mB = perMinOK ? mExp(B) : 0;
  const perMinStr = (v, m, fights) => {
    if (m) { const r = v / m; return (v > 0 && r < 0.05 ? '<0.1' : r.toFixed(1)) + '/min'; }
    return fights ? (v / fights).toFixed(1) + '/fight' : '';
  };
  const sumCell = (G, key, i) => G[key].reduce((s, c) => s + c[i], 0);
  const lA = sumCell(A, 'cells', 0), aA = sumCell(A, 'cells', 1);
  const lB = sumCell(B, 'cells', 0), aB = sumCell(B, 'cells', 1);
  const dlA = sumCell(A, 'cellsD', 0), daA = sumCell(A, 'cellsD', 1);
  const dlB = sumCell(B, 'cellsD', 0), daB = sumCell(B, 'cellsD', 1);
  h += '<div class="mh-sec">Significant strikes</div>';
  h += mhCmp('Landed',
    { txt: lA + '/' + aA, sub: _mhPct(lA, aA) + ' accurate · ' + perMinStr(lA, mA, A.fights), frac: aA ? lA/aA : 0 },
    { txt: lB + '/' + aB, sub: _mhPct(lB, aB) + ' accurate · ' + perMinStr(lB, mB, B.fights), frac: aB ? lB/aB : 0 },
    { lead: _mhLeadProp(lA, aA, lB, aB) });
  // Not accented — a long bar here is strikes eaten, same convention as "Time spent
  // under control" on the grappling tab: this section describes, it doesn't grade.
  h += mhCmp('Absorbed',
    { txt: dlA + '/' + daA, sub: _mhPct(dlA, daA) + ' accurate · ' + perMinStr(dlA, mA, A.fights), frac: daA ? dlA/daA : 0 },
    { txt: dlB + '/' + daB, sub: _mhPct(dlB, daB) + ' accurate · ' + perMinStr(dlB, mB, B.fights), frac: daB ? dlB/daB : 0 });

  // NO GREEN/RED ON THIS SECTION, AND IT IS THE ONE PLACE I'M NOT FOLLOWING THE
  // PROFILE BARS. Every other row here has a direction: landing more is better,
  // getting hit less is better. A SHARE HAS NO DIRECTION. Throwing 13% of your
  // offense at legs against a 10% division median doesn't make you better than the
  // man at 7% — it makes you a different fighter. Colouring it green would assert
  // that head-hunting beats leg-kicking, which is not a thing this data knows.
  // So: the division tick, so you can see he's unusual, and no verdict about it.
  // ONE SECTION BECAME TWO, BECAUSE IT WAS MIXING TWO QUESTIONS.
  //
  // It used to list "head at range / body at range / leg kicks / ground strikes" as
  // shares of TOTAL offense — which puts a POSITION fact (ground strikes: you throw
  // them because you're on the ground) in a list with POSITION x TARGET facts, and
  // makes every one of them move when a fighter's grappling changes. Measured over
  // 524 fighters, head-share-of-total correlates 0.703 with share-of-offense-at-
  // range: most of "he head-hunts" was "he stays standing".
  //
  // Split, both are clean and neither moves the other:
  //   WHERE THE FIGHT HAPPENS — at range / clinch / ground, share of total.
  //   WHAT THEY THROW AT RANGE — head / body / legs, share of DISTANCE offense.
  //                              corr with distance-share: 0.059. A real choice.
  // It also makes the section agree with the read, which cites exactly these two
  // denominators. Before, the read said Duncan goes to the legs 28% of the time
  // while this section said 23%, on the same screen, both correct.
  const tot = G => G.cells.reduce((s,c) => s + c[1], 0) || 1;
  const distTot = G => (G.cells[0][1] + G.cells[1][1] + G.cells[2][1]) || 1;
  const tA = tot(A), tB = tot(B);
  const dA = distTot(A), dB = distTot(B);

  // NO DIVISION TICK ON THESE TWO SECTIONS. Everywhere else the tick answers "is
  // this good?", which needs a yardstick. Here the question is "what does this
  // fighter do?" — and there is no better or worse about it. A leg-kicker is not
  // failing to be a head-hunter, and marking where the median welterweight sits
  // implies he is. The read still calls out a genuinely unusual habit; the bars
  // just describe the two men.
  //
  // THE BAR IS THE PERCENTAGE. 11% FILLS 11%.
  //
  // This used to scale to the bigger of the two shares — frac = ra / max(ra, rb) —
  // so whoever led a row got a FULL bar whatever the number beside it said. Usman
  // throws 11% of his offense in the clinch and 18% on the ground, and both bars ran
  // the whole track. Reported as confusing, and it is worse than confusing: the bar
  // was answering "who does this more?" while the number next to it answered "how
  // much?", and nothing on screen said they were different questions. Meanwhile
  // "What lands on them" two sections below has always drawn frac = the rate itself.
  // Two bar languages in one tab, no way to tell them apart.
  //
  // THE DEFENCE WAS "at 5% of offense both clinch bars would be invisible slivers",
  // AND IT DOESN'T SURVIVE A RULER: at 5% the bar draws 20px on desktop (400px
  // track) and 6px on a phone. Not invisible — small, which is the truth. The cure
  // was drawing 11% as 400px, a 36x exaggeration to avoid a 20px one.
  //
  // Absolute also makes the three rows comparable to EACH OTHER, which is the point
  // of the section: they are shares of one fighter's output and they sum to 100, so
  // at range 74% / clinch 11% / ground 14% now looks like what it is. Normalising
  // each row on its own made the clinch row as loud as the range row, i.e. it hid
  // the finding.
  const shareRow = (label, ra, rb) => mhCmp(label,
    { txt: Math.round(ra*100) + '%', sub: null, frac: ra },
    { txt: Math.round(rb*100) + '%', sub: null, frac: rb });

  h += '<div class="mh-sec">Where the fight happens <span>share of everything they throw</span></div>';
  for (const [g, label] of [[0,'At range'],[1,'In the clinch'],[2,'On the ground']]) {
    const ra = (A.cells[g*3][1]+A.cells[g*3+1][1]+A.cells[g*3+2][1]) / tA;
    const rb = (B.cells[g*3][1]+B.cells[g*3+1][1]+B.cells[g*3+2][1]) / tB;
    h += shareRow(label, ra, rb);
  }

  h += '<div class="mh-sec">What they throw at range <span>share of what they throw standing</span></div>';
  for (const [t, label] of [[0,'Head'],[1,'Body'],[2,'Legs']]) {
    h += shareRow(label, A.cells[t][1]/dA, B.cells[t][1]/dB);
  }
  // KNOCKDOWNS RIDE ALONG HERE. They are the one striking number that isn't in the
  // grid at all, so they have nowhere else to live. Dropped entirely when neither
  // man has one, rather than printed as 0 vs 0, which reads as a measured tie
  // instead of the absence it is.
  //
  // THE TOTAL IS THE HEADLINE, THE RATE IS THE COMPARISON. Over a full career the
  // count alone is a career-length reading (corr 0.602 with fights fought), so the
  // BAR and the accent run off knockdowns-per-fight while the number a fan actually
  // recognises still prints. Both are true; only one of them is a fair comparison.
  if (A.kd || B.kd) {
    const p15 = _mhPer15Bout(A, B);
    const eA = _mhExpOf(A, p15), eB = _mhExpOf(B, p15);
    const rA = _mhRate(A.kd, eA), rB = _mhRate(B.kd, eB);
    const mK = Math.max(rA, rB, 0.01);
    h += mhCmp('Knockdowns scored',
      { txt: String(A.kd), sub: _mhIn(A.sFights), frac: rA/mK },
      { txt: String(B.kd), sub: _mhIn(B.sFights), frac: rB/mK },
      { lead: _mhLeadRate(A.kd, eA, B.kd, eB) });
  }

  const gA = mhGrid(A, 'cells', n1), gB = mhGrid(B, 'cells', n2);
  h += '<div class="mh-sec">How well it lands <span>accuracy by position and target · landed / thrown</span></div>';
  h += '<div class="mh-grids">' +
    '<div><div class="mh-grid-t">' + escHtmlAttr(_ddLast(n1)) + '</div>' + gA.html + '</div>' +
    '<div><div class="mh-grid-t">' + escHtmlAttr(_ddLast(n2)) + '</div>' + gB.html + '</div></div>';
  // Two lines: the scale, then what it's measured AGAINST. That second line is not
  // decoration — without it a reader takes the colour for the raw percentage and
  // misreads every cell, since nobody is near 100% at head-at-range.
  // The dashed key only appears when a dashed cell is actually on screen — a legend
  // explaining something you can't see is just more words. mhGrid tags 'thin' into
  // srcs when it renders one.
  const gs = new Set([...gA.srcs, ...gB.srcs]);
  h += '<div class="mh-gk"><span class="mh-gk-row">Worse<span class="mh-gk-sw"></span>Better' +
       (gs.has('thin') ? '<span class="mh-gk-thin"></span>under ' + _MH_FLOOR + ' thrown, too few to rate' : '') +
       '</span><span class="mh-gk-sub">' + mhBaseLabel(gs) + '</span></div>';

  // WHAT LANDS ON HIM — the one section where the accent runs backwards, because
  // the number is a beating. Below your division's median = green.
  const dSrc = new Set();
  let dRows = '';
  for (const [p,t,label] of _MH_LANES) {
    const i = _MH_GI(p,t);
    const a = A.cellsD[i], b = B.cellsD[i];
    if (a[1] < _MH_FLOOR && b[1] < _MH_FLOOR) continue;
    const ra = a[1] ? a[0]/a[1] : 0, rb = b[1] ? b[0]/b[1] : 0;
    const nA = a[1] >= _MH_FLOOR ? mhNorm(n1, 'allow', i) : null;
    const nB = b[1] >= _MH_FLOOR ? mhNorm(n2, 'allow', i) : null;
    if (nA) dSrc.add(nA.src);
    if (nB) dSrc.add(nB.src);
    dRows += mhCmp(label,
      { txt: a[1] < _MH_FLOOR ? '—' : _mhPct(a[0],a[1]), sub: a[0] + '/' + a[1], frac: ra },
      { txt: b[1] < _MH_FLOOR ? '—' : _mhPct(b[0],b[1]), sub: b[0] + '/' + b[1], frac: rb },
      { normL: nA ? nA.med : null, normR: nB ? nB.med : null,
        // Each man judged against his OWN division, independently — this is not a
        // comparison between the two of them, it's two verdicts side by side.
        // lowerIsBetter: getting hit less than your peers is the good end.
        gradeL: _mhGrade(ra, a[1], nA, true),
        gradeR: _mhGrade(rb, b[1], nB, true) });
  }
  h += '<div class="mh-sec">What lands on them <span>how often strikes land vs the division median</span></div>';
  h += dRows;
  h += mhSheetBtn('striking');
  return h;
}

// The sheet button, at the foot of whichever tab you're reading — a card of THIS
// tab, not of the bout. Rendered as markup rather than wired here because the body
// is innerHTML'd on every tab switch, so a listener attached now would be thrown
// away; the delegated handler on the modal survives (see mhSheetClick).
function mhSheetBtn(tab){
  if (typeof window === 'undefined' || !window.GL_SHEET) return '';
  return '<button type="button" class="gl-sheet-btn mh-sheet-btn" data-mh-sheet="' + tab + '">' +
         '↓ Generate ' + tab + ' sheet</button>';
}

function mhGrappling(A, B, n1, n2){
  let h = mhReadBlock(A, B, n1, n2, 'grap',
    'Neither man separates from the other on the mat by enough to lead with.');

  const base = window.GRID_BASE || {};
  // One decision for the whole tab: can both men be timed? Everything below shares
  // it, so no two rows can silently speak different units.
  const p15 = _mhPer15Bout(A, B);
  const eA = _mhExpOf(A, p15), eB = _mhExpOf(B, p15);
  h += '<div class="mh-sec">Takedowns</div>';
  // THIS ROW SURVIVED THE WINDOW CHANGE UNTOUCHED, AND THAT IS THE WHOLE LESSON.
  // Its bar was always tdL/tdA — a rate, with the exposure already divided out —
  // so opening it from 8 fights to a career changes the precision and not the
  // meaning. corr(fights, accuracy) = -0.025. Every row that needed fixing today
  // is a row that was dividing by nothing.
  //
  // Volume is still worth seeing, so it rides in the sub: 15 of 33 at 45% is a
  // different fighter from 15 of 33 spread over twice as long.
  h += mhCmp('Takedowns landed',
    { txt: A.tdL + '/' + A.tdA, sub: _mhPct(A.tdL, A.tdA) + ' accurate · ' + _mhPerShort(A.tdL, eA, p15), frac: A.tdA ? A.tdL/A.tdA : 0 },
    { txt: B.tdL + '/' + B.tdA, sub: _mhPct(B.tdL, B.tdA) + ' accurate · ' + _mhPerShort(B.tdL, eB, p15), frac: B.tdA ? B.tdL/B.tdA : 0 },
    { lead: _mhLeadProp(A.tdL, A.tdA, B.tdL, B.tdA) });
  // Takedowns landed carries a RATE rather than "in N fights": it is the one count
  // here that is never sparse enough to round away, and volume is the half of a
  // wrestler that accuracy alone misses — 5.7 per 15 and 0.4 per 15 are different
  // men at identical accuracy. This sub is also the number that has to match the
  // fighter's own profile page (FIGHTER_STATS.tdLanded), which is per 15 minutes.
  const sA = A.tdAgA ? (A.tdAgA-A.tdAgL)/A.tdAgA : 0, sB = B.tdAgA ? (B.tdAgA-B.tdAgL)/B.tdAgA : 0;
  h += mhCmp('Takedowns stopped',
    { txt: (A.tdAgA-A.tdAgL) + '/' + A.tdAgA, sub: A.tdAgA ? _mhPct(A.tdAgA-A.tdAgL, A.tdAgA) : 'never shot on', frac: sA },
    { txt: (B.tdAgA-B.tdAgL) + '/' + B.tdAgA, sub: B.tdAgA ? _mhPct(B.tdAgA-B.tdAgL, B.tdAgA) : 'never shot on', frac: sB },
    { norm: base.tdStop ? base.tdStop[0] : null,
      lead: _mhLeadProp(A.tdAgA-A.tdAgL, A.tdAgA, B.tdAgA-B.tdAgL, B.tdAgA) });
  // CONTROL TIME IS THE ROW THE CAREER WINDOW HURT MOST, because it is a raw
  // accumulator with no denominator anywhere in it (corr 0.484 with fights fought).
  // On career totals the bar would simply rank the two men by seniority. The total
  // prints — 50 minutes is a fact a fan can feel — and the bar is per fight, which
  // is the only version of it that compares two different careers.
  const cA = _mhRate(A.ctrl, eA), cB = _mhRate(B.ctrl, eB);
  const mC = Math.max(cA, cB, 1);
  h += mhCmp('Control time',
    { txt: _mhMins(A.ctrl), sub: _mhShort(cA) + ' ' + _mhUnit(p15), frac: cA/mC },
    { txt: _mhMins(B.ctrl), sub: _mhShort(cB) + ' ' + _mhUnit(p15), frac: cB/mC },
    { lead: _mhLeadRatio(cA, cB, 1.25) });
  // Not accented: a long bar is time on your back. Same reason as "what lands on him".
  const caA = _mhRate(A.ctrlAg, eA), caB = _mhRate(B.ctrlAg, eB);
  const mCa = Math.max(caA, caB, 1);
  h += mhCmp('Time spent under control',
    { txt: _mhMins(A.ctrlAg), sub: _mhShort(caA) + ' ' + _mhUnit(p15), frac: caA/mCa },
    { txt: _mhMins(B.ctrlAg), sub: _mhShort(caB) + ' ' + _mhUnit(p15), frac: caB/mCa });

  // There is no "positions gained" section. See the measurement in _ddGrid: the
  // advance and slam fields are 100% present and 99.4% zero, so it would have been
  // a grid of noughts wearing the clothes of an insight.
  //
  // Both of these are SPARSE — sub attempts land on 22% of fighter-fights,
  // reversals on 9% — so the row is dropped entirely when both men are at zero
  // rather than printed as "0 vs 0", which reads as a measured tie between two
  // fighters instead of the absence it is.
  const ex = [
    ['Submission attempts', A.sub, B.sub],
    ['Reversals', A.rev, B.rev]
  ].filter(r => r[1] || r[2]);
  if (ex.length) {
    h += '<div class="mh-sec">On the mat</div>';
    for (const [lab, a, b] of ex) {
      // Per 15 min for the bar and the accent, same as every other count here.
      const ra = _mhRate(a, eA), rb = _mhRate(b, eB);
      const m = Math.max(ra, rb, 0.01);
      h += mhCmp(lab, { txt: String(a), sub: _mhIn(A.sFights), frac: ra/m },
                       { txt: String(b), sub: _mhIn(B.sFights), frac: rb/m },
                       { lead: _mhLeadRate(a, eA, b, eB) });
    }
  }
  h += mhSheetBtn('grappling');
  return h;
}
// There is no footer. It carried the provenance ("last N UFC fights each, from
// official box scores") and the tick's meaning, both of which now live on the
// section headers that actually own them — which is also where the N is honest,
// since the striking totals count FIGHT_STATS fights and the grid counts
// FIGHT_GRID fights, and one footer had to pick one and be wrong about the other.

function mhRenderBody(){
  const body = document.getElementById('mh-body');
  if (!body || !_mhState) return;
  const { A, B, n1, n2, tab, resultFilter } = _mhState;
  // NULL means "no grid data for this fighter at all" — unrelated to the filter,
  // the pre-existing case where the grid simply doesn't cover him. That still
  // blocks the whole panel; there's nothing to fall back to.
  if (!A || !B) {
    body.innerHTML = '<div class="mh-empty">No breakdown available for this bout.</div>';
    return;
  }
  const rf = resultFilter === 'win' ? 'wins' : resultFilter === 'loss' ? 'losses' : null;
  // noData (see _ddGrid) means the grid HAS this fighter, just zero rows match
  // the filter — e.g. an undefeated man under "Losses". If BOTH sides are empty
  // there's nothing to compare (every bar would read 0 vs 0), so say that
  // plainly. If only ONE side is empty, that's exactly the case a user asked to
  // fix: the other man's numbers are real and worth showing, so render normally
  // and just label which side is empty and why, rather than blocking the panel.
  if (A.noData && B.noData) {
    body.innerHTML = '<div class="mh-empty">Neither fighter has any UFC ' + rf + ' on record.</div>';
    return;
  }
  let note = '';
  if (A.noData || B.noData) {
    const emptyName = A.noData ? n1 : n2, shownName = A.noData ? n2 : n1;
    // "UFC" is load-bearing here, not decoration: a fighter can easily have real
    // wins/losses from the regional circuit that never touch this stat set, and
    // "has no wins on record" reads as a claim about their whole career, not the
    // UFC-only window this grid actually tracks.
    note = '<div class="mh-filter-note">' + escHtmlAttr(emptyName) + ' has no UFC ' + rf +
      ' on record — showing ' + escHtmlAttr(shownName) + '\'s numbers only.</div>';
  }
  try {
    body.innerHTML = note + (tab === 'grappling' ? mhGrappling(A, B, n1, n2)
                                                  : mhStriking(A, B, n1, n2));
  } catch (e) {
    body.innerHTML = '<div class="mh-empty">Couldn\'t render this breakdown.</div>';
  }
  // DELEGATED, AND ONCE. mhRenderBody runs on every tab switch, so binding the
  // button here directly would attach a fresh listener to a fresh node each time —
  // fine — but binding to the BODY would stack them. The flag keeps it to one.
  if (body && !body._mhSheetWired) {
    body._mhSheetWired = true;
    body.addEventListener('click', mhSheetClick);
  }
}
function mhSheetClick(e){
  const btn = e.target && e.target.closest && e.target.closest('[data-mh-sheet]');
  if (!btn || !_mhState || !window.GL_SHEET) return;
  e.stopPropagation();
  const { n1, n2, meta } = _mhState;
  const which = btn.getAttribute('data-mh-sheet');
  // The event name lives in the page header, not in meta — same place the
  // "Generate matchup sheet" button reads it from.
  const evLabel = ((document.getElementById('home-event-name') || {}).textContent || '').trim();
  const info = { event: evLabel || 'UFC', date: (meta && meta.date) || '',
                 weightClass: (meta && meta.wc) || '' };
  // The hub is open, so FIGHT_GRID is already fetched and _ddGrid resolves — this
  // button cannot be reached before that.
  if (which === 'grappling') window.GL_SHEET.grappling(n1, n2, info);
  else window.GL_SHEET.striking(n1, n2, info);
}

function mhTab(t){
  if (!_mhState) return;
  _mhState.tab = t;
  document.querySelectorAll('#mh-tabs .mh-tab').forEach(b => b.classList.toggle('on', b.dataset.mhTab === t));
  mhRenderBody();
  const body = document.getElementById('mh-body'); if (body) body.scrollTop = 0;
}

// All / Wins / Losses. Lives beside mhTab rather than inside it: the filter is
// shared state across BOTH tabs (see the .mh-filter CSS comment), so switching it
// re-derives A/B from the grid data already in memory — no refetch, it's the same
// ~245KB payload from loadFightGrid(), just re-aggregated over a subset of rows.
// If the grid hasn't loaded yet (still "Loading…"), _mhState.A/B are still null;
// the loadFightGrid().then() callback in openMatchupHub reads _mhState.resultFilter
// at that point, so a filter click during the initial load still takes effect
// once the fetch resolves — nothing here needs to guard against that race.
function mhFilter(f){
  if (!_mhState || _mhState.resultFilter === f) return;
  _mhState.resultFilter = f;
  document.querySelectorAll('#mh-filter .mh-filter-btn').forEach(b => b.classList.toggle('on', b.dataset.mhFilter === f));
  if (_mhState.A || _mhState.B) {
    _mhState.A = _ddGrid(_mhState.n1, f);
    _mhState.B = _ddGrid(_mhState.n2, f);
  }
  mhRenderBody();
  const body = document.getElementById('mh-body'); if (body) body.scrollTop = 0;
}

function mhRecord(n){
  if (typeof FIGHTERS === 'undefined') return '';
  const e = FIGHTERS.find(x => x.name === n) || FIGHTERS.find(x => _gridNorm(x.name) === _gridNorm(n));
  return (e && e.record) || '';
}

function mhRenderHeader(){
  const hd = document.getElementById('mh-hd');
  if (!hd || !_mhState) return;
  const { n1, n2, meta } = _mhState;
  // The avatar is wrapped rather than styled directly: _fsAva() hard-codes 40px
  // inline and is shared with the fight modal, so the wrapper is where this header
  // gets to shrink it on a phone without reaching into someone else's component.
  const side = (n, right) => '<div class="mh-hd-f' + (right ? ' r' : '') +
    '" onclick="mhOpenFighter(\'' + escJsAttr(n) + '\')" role="button" tabindex="0">' +
    '<span class="mh-hd-av">' + _fsAva(n) + '</span>' +
    '<div class="mh-hd-tx"><div class="mh-hd-nm">' + escHtmlAttr(n) + '</div>' +
    '<div class="mh-hd-rc">' + escHtmlAttr(mhRecord(n)) + '</div></div></div>';
  const sub = [meta.wc, meta.rounds].filter(Boolean).join(' · ');
  hd.innerHTML = side(n1, false) +
    '<div class="mh-hd-mid"><div class="mh-hd-vs">VS</div>' +
    (sub ? '<div class="mh-hd-sub">' + escHtmlAttr(sub) + '</div>' : '') + '</div>' +
    side(n2, true);
}

function mhOpenFighter(n){
  closeMatchupHub();
  setTimeout(function(){ if (typeof openFighterByName === 'function') openFighterByName(n); }, 80);
}

function _mhKey(e){ if (e.key === 'Escape') closeMatchupHub(); }

function openMatchupHub(n1, n2, meta){
  const box = document.getElementById('mh-box'), ov = document.getElementById('mh-overlay');
  if (!box || !ov) return;
  _mhState = { n1, n2, A: null, B: null, tab: 'striking', meta: meta || {}, resultFilter: 'all' };
  mhRenderHeader();
  document.querySelectorAll('#mh-tabs .mh-tab').forEach(b => b.classList.toggle('on', b.dataset.mhTab === 'striking'));
  // Reset the filter pills too — reopening on a different bout with the last
  // bout's "Losses" still selected would silently apply someone else's filter.
  document.querySelectorAll('#mh-filter .mh-filter-btn').forEach(b => b.classList.toggle('on', b.dataset.mhFilter === 'all'));
  const body = document.getElementById('mh-body');
  body.innerHTML = '<div class="mh-loading">Loading…</div>';
  body.scrollTop = 0;
  ov.style.display = 'block'; ov.style.opacity = '0';
  box.classList.add('mh-on'); box.style.opacity = '0';
  box.style.transform = 'translate(-50%,-50%) translateY(8px)';
  requestAnimationFrame(function(){ requestAnimationFrame(function(){
    ov.style.opacity = '1'; box.style.opacity = '1';
    box.style.transform = 'translate(-50%,-50%)';
  }); });
  if (typeof lockPageScroll === 'function') lockPageScroll();
  document.addEventListener('keydown', _mhKey);
  // THE FETCH HAPPENS HERE, not on page load: ~245KB for a panel most visitors
  // never open. Concurrent opens share one promise.
  loadFightGrid().then(function(){
    // Closed, or reopened on a different bout, while the fetch was in flight.
    if (!_mhState || _mhState.n1 !== n1 || _mhState.n2 !== n2) return;
    _mhState.A = _ddGrid(n1, _mhState.resultFilter); _mhState.B = _ddGrid(n2, _mhState.resultFilter);
    mhRenderBody();
  }).catch(function(){
    if (body) body.innerHTML = '<div class="mh-empty">Couldn\'t load the breakdown.</div>';
  });
}

function closeMatchupHub(){
  const box = document.getElementById('mh-box'), ov = document.getElementById('mh-overlay');
  if (!box || !ov || !box.classList.contains('mh-on')) return;
  ov.style.opacity = '0';
  box.style.opacity = '0';
  box.style.transform = 'translate(-50%,-50%) translateY(8px)';
  setTimeout(function(){ ov.style.display = 'none'; box.classList.remove('mh-on'); }, 220);
  _mhState = null;
  if (typeof unlockPageScroll === 'function') unlockPageScroll();
  document.removeEventListener('keydown', _mhKey);
}
window.openMatchupHub = openMatchupHub;
window.closeMatchupHub = closeMatchupHub;
window.mhTab = mhTab;
window.mhFilter = mhFilter;
window.mhOpenFighter = mhOpenFighter;

// THE READ — the sentence that turns a table into an argument.
//
// IT STATES DISPARITIES, IT DOES NOT RECOMMEND PATHS. That distinction is the whole
// design, and it is what lets this ship while the ranking cannot.
//   "Usman has stopped 27 of 32 takedowns; Du Plessis 8 of 23."   <- a fact
//   "Usman's best path is wrestling."                             <- a claim
// The second needs the model to know that ground-and-pound is gated behind a
// takedown and head-at-range is gated behind nothing. It doesn't. So it would
// happily advise a man to ground-and-pound someone he cannot take down — measured,
// on the first real bout this ran against. Until that's solved with a measurement
// rather than a guess, the panel reports what IS and lets the reader draw the line.
// A fan who reads "8 of 23 vs 27 of 32" has already worked out where the fight goes.
//
// z ONLY PICKS, IT NEVER PRINTS. Choosing which of six disparities to lead with
// requires comparing gaps across axes with different spreads (takedown defense
// sd ~19 points, head accuracy sd ~8 — the same 20-point gap is ordinary in one and
// enormous in the other), so the selection is z-scored against baselines measured at
// build time. The output is always counts, because "95th percentile" means nothing
// to someone watching a fight.
//
// `domain` ('strike' | 'grap' | null) lets the hub's Striking and Grappling tabs
// each lead with their own strongest line while Overview takes the strongest of
// all. It PARTITIONS THE EXISTING CANDIDATES AND NOTHING ELSE — no new claim, no
// new threshold, no second engine that can drift from this one. Every sentence a
// tab prints is one this function was already willing to print.
function ddRead(A, B, n1, n2, domain){
  const base = window.GRID_BASE || {};
  const L1 = escHtmlAttr(_ddLast(n1)), L2 = escHtmlAttr(_ddLast(n2));
  const GI = (p,t) => ['dist','clinch','ground'].indexOf(p)*3 + ['head','body','leg'].indexOf(t);
  const cands = [];

  // SIGNED. NOT Math.abs. THIS WAS A LIE GENERATOR AND IT RAN FOR A DAY.
  //
  // The old helper was `Math.abs(v - mean) / sd`, and the lane picker was
  // `openIsA = ra > rb` — whoever of the TWO allowed more, regardless of the norm.
  // Together they printed, of 38 "gets caught more than most" claims on this card,
  // EIGHT that were flatly false:
  //     "Rodriguez gets caught to the body more than most: 58% ... against a 65% norm"
  //     "Elliott gets caught to the head at range more than most: 25% ... vs 34%"
  //     "Dern gets caught to the head at range more than most: 34% ... vs 34%"
  // Every one of those men is at or BETTER than the norm. Math.abs let an unusually
  // GOOD defender clear the significance gate, and `ra > rb` then handed him the
  // sentence written for the bad one. The panel cited the very number that refuted
  // it, in the same breath. Nobody caught it because both halves are individually
  // reasonable and the output is fluent.
  //
  // Now: zs() is SIGNED, each man is judged against HIS OWN norm rather than
  // against the other man, and the direction picks the verb. Being unusually hard
  // to hit is its own sentence, not a mislabelled version of the opposite one.
  const zs = (v, norm) => (norm && norm.spread) ? (v - norm.med) / norm.spread : 0;

  // "against a 88% norm" and "a 8% norm" were both shipping. Eight, eleven,
  // eighteen and the eighties all take "an".
  const aan = n => (n === 8 || n === 11 || n === 18 || (n >= 80 && n <= 89)) ? 'an' : 'a';
  const vs = n => ', vs ' + aan(n) + ' ' + n + '% norm.';
  // The same clause without the full stop, for predicates that get joined.
  const vsn = n => ', vs ' + aan(n) + ' ' + n + '% norm';

  // ONE PHRASE PER LANE, NOT ONE TEMPLATE FOR ALL OF THEM. A generic sentence has to
  // fit every hole it can be dropped into, and the result was "throws unusually much
  // on the ground" — grammatical mush that a fan would never say. These are the
  // words the sport actually uses, so each lane gets its own.
  //
  // The `lo` side is factual, never a sneer: "less accurate to the body" and not
  // "misses the body". 54% of body shots landing is below par, not a failure, and
  // the panel doesn't get to editorialise past what the number carries.
  const DEF = {                                             // what LANDS ON him
    0: { hi: 'is open at range',           lo: 'is hard to hit at range',        what: 'head strikes' },
    1: { hi: 'is open to the body',        lo: 'protects the body well',         what: 'body shots' },
    2: { hi: 'is open to leg kicks',       lo: 'rarely gets caught by leg kicks', what: 'leg kicks' },
    // "takes damage on the mat" was the old wording and it overreached: the grid
    // counts strikes that LAND, not damage. A landed strike is not a hurt fighter.
    6: { hi: 'gets hit on the mat',        lo: 'stays clean on the mat',         what: 'ground strikes' },
  };
  const OFF = {                                             // what HE lands
    0: { hi: 'is accurate at range',       lo: 'is less accurate at range',      what: 'head strikes' },
    1: { hi: 'is accurate to the body',    lo: 'is less accurate to the body',   what: 'body shots' },
    2: { hi: 'lands leg kicks cleanly',    lo: 'is less accurate with leg kicks', what: 'leg kicks' },
    6: { hi: 'is accurate on the mat',     lo: 'is less accurate on the mat',    what: 'ground strikes' },
  };
  // COMPARATIVE, NOT AN IDENTITY. "Hooper is a clinch fighter" turns 14% of his
  // output into a label for the whole man — a noun the number cannot support, and
  // it reads as though the panel has decided that's all he does. These say more
  // than most, which is exactly and only what was measured.
  //
  // AND NOT "spends more TIME in the clinch" either, tempting as that phrasing is:
  // the grid counts STRIKES THROWN, not seconds. A fighter can spend a round in the
  // clinch and throw nothing there. Say what was counted.
  const POS = {
    0: { hi: 'throws more at range than most',         lo: 'throws less at range than most' },
    1: { hi: 'throws more in the clinch than most',    lo: 'throws less in the clinch than most' },
    2: { hi: 'throws more ground-and-pound than most', lo: 'throws less ground-and-pound than most' },
  };

  // Takedown defense — usually the story, and the one axis where the spread is wide
  // enough that a gap is almost always meaningful.
  // GRADED, WITH A FLOOR. The first version said "is far harder to take down" for
  // Cannonier at 16 of 23 (70%) against Duncan's 19 of 30 (63%) — a seven-point
  // gap — and for McMillen at 83% vs 78%. No threshold, so the phrase fired on
  // noise, which is the "won't be wrestled" overclaim in a new costume: language
  // that outruns what the numbers can carry. A gap has to be real AND large before
  // it gets a strong verb, and the verb scales with the gap.
  if (A.tdAgA >= 8 && B.tdAgA >= 8) {
    const sA = (A.tdAgA - A.tdAgL) / A.tdAgA, sB = (B.tdAgA - B.tdAgL) / B.tdAgA;
    const gap = Math.abs(sA - sB);
    const sd = (base.tdStop && base.tdStop[1]) || 0.196;
    if (gap >= sd) {                    // at least one full roster sd apart
      const hi = sA > sB, hiN = hi ? A : B, loN = hi ? B : A;
      const verb = gap >= sd * 2 ? ' is far harder to take down: '
                 : ' is harder to take down: ';
      cands.push({ dom: 'grap', w: gap / sd,
        t: (hi ? L1 : L2) + verb + (hiN.tdAgA - hiN.tdAgL) + ' of ' + hiN.tdAgA +
           ' stopped, against ' + (loN.tdAgA - loN.tdAgL) + ' of ' + loN.tdAgA +
           ' for ' + (hi ? L2 : L1) + '.' });
    }
  }
  // Control time — the other half of the same story, in minutes a fan can feel.
  //
  // PER FIGHT, ALL THE WAY THROUGH. This was career seconds against career seconds,
  // which over a full record ranks by seniority: a journeyman with 30 fights beats a
  // dominant wrestler with 6 on the total while being nowhere near him per fight.
  // Control time has no trials to Poisson-test, so the exposure has to be divided
  // out by hand — the gate, the ratio that sets the weight, and the printed minutes
  // are now all the per-fight number.
  const kA = _mhRate(A.ctrl, _mhExpOf(A, _mhPer15Bout(A,B))),
        kB = _mhRate(B.ctrl, _mhExpOf(B, _mhPer15Bout(A,B)));
  if (kA + kB > 60) {                       // a minute of the clock between them, or there's no story
    const aHi = kA > kB;
    const hi = aHi ? kA : kB, lo = aHi ? kB : kA;
    const ratio = (lo > 15) ? hi / lo : 9;  // near-zero on one side: lopsided by definition
    if (ratio >= 1.8) cands.push({ dom: 'grap', w: Math.min(ratio, 4),
      t: (aHi ? L1 : L2) + ' controls ' + _mhMins(hi) + ' of every 15 minutes; ' +
         (aHi ? L2 : L1) + ' ' + _mhMins(lo) + '.' });
  }
  // DEFENSE — a lane where a man is unusually open, OR unusually hard to hit.
  //
  // EACH MAN AGAINST HIS OWN DIVISION, INDEPENDENTLY. Not against each other: "who
  // allows more of the two" is a different question from "who is unusual", and
  // conflating them is what produced the eight false claims (see zs above). Both
  // men can be candidates from the same lane, or neither.
  //
  // Uses the SAME baseline the grid shades against (mhNorm -> division median),
  // so the prose and the colour cite the same number. They used to disagree: the
  // grid said "vs your division" while the read quoted a card-wide mean.
  const LANES = [['dist','head','the head at range'],['dist','body','the body'],
                 ['dist','leg','leg kicks'],['ground','head','ground strikes']];
  for (const [p,t,label] of LANES) {
    const i = GI(p,t);
    for (const [me, him, LM, nm] of [[A,B,L1,n1],[B,A,L2,n2]]) {
      const c = me.cellsD[i];
      if (c[1] < 25) continue;
      const r = c[0]/c[1];
      const norm = mhNorm(nm, 'allow', i);
      if (!norm) continue;
      const z = zs(r, norm);
      if (Math.abs(z) < 1.1) continue;

      // THE PREREQUISITE, AND I THOUGHT I HAD SIDESTEPPED IT.
      //
      // The plan was: state disparities, never recommend paths, and the gating
      // problem goes away. It doesn't. "Usman gets caught to ground strikes more
      // than most" is a disparity by grammar and a path by implication — it is only
      // worth saying to a man who can put him on the ground, and Du Plessis stops 8
      // of 23. A fact whose relevance depends on an unstated condition is not a
      // safer kind of claim; it is the same claim with the condition hidden.
      //
      // So the ground lane requires the OTHER man to actually get there. Applies to
      // the flattering direction too — "hard to hit on the ground" is just as empty
      // against someone who can't take him down.
      if (p === 'ground') {
        const canGet = him.tdA >= 4 && me.tdAgA >= 4 &&
                       (him.tdL / Math.max(1, him.tdA)) >= 0.25 &&
                       (me.tdAgL / Math.max(1, me.tdAgA)) >= 0.30;
        if (!canGet) continue;
      }
      const pc = Math.round(r*100), np = Math.round(norm.med*100);
      // NO PRONOUNS ANYWHERE. 13% of the fighters on this card are women, and the
      // original sentences avoided "he" entirely — I reintroduced it and printed
      // "Kline aims unusually often at ground strikes: 13% of everything HE throws".
      // Naming them is also just clearer when two people are being compared.
      const d = DEF[i];
      // "CONCEDES", SO THE NAME ONLY HAS TO APPEAR ONCE.
      //
      // This read "Makhachev protects the body well: only 45% of body shots aimed at
      // Makhachev land, vs a 64% norm" — the surname twice in one sentence, and a
      // third time in the sentence beside it. The repetition was doing real work:
      // "45% of body shots land" is ambiguous between what he lands and what lands
      // ON him, and "aimed at <name>" was how the two were told apart. `concedes`
      // carries that distinction in the verb, so the subject can be stated once and
      // then shared — which is what lets two findings become one sentence.
      //
      // Not a pronoun, for the reason the pronouns came out in the first place: 13%
      // of this card is women, and "aimed at him" is wrong for eight of them.
      cands.push({ dom: 'strike', w: Math.abs(z), who: LM, lane: i, kind: 'def',
        pred: (z > 0 ? d.hi : d.lo) + ' (concedes ' + (z > 0 ? '' : 'only ') +
              pc + '% on ' + d.what + vsn(np) + ')' });
    }
  }

  // OFFENSE — a lane a man lands unusually well, or unusually badly. Same shape,
  // same baseline, and it was simply missing: the read had nothing to say about
  // what either man DOES, only what gets done to him. That is most of why so many
  // bouts came back "no clear edge".
  for (const [p,t,label] of LANES) {
    const i = GI(p,t);
    for (const [me, him, LM, nm] of [[A,B,L1,n1],[B,A,L2,n2]]) {
      const c = me.cells[i];
      if (c[1] < 25) continue;
      const r = c[0]/c[1];
      const norm = mhNorm(nm, 'acc', i);
      if (!norm) continue;
      const z = zs(r, norm);
      if (Math.abs(z) < 1.2) continue;      // a touch stricter than defense: more lanes, more chances to fire
      if (p === 'ground') {
        const canGet = me.tdA >= 4 && him.tdAgA >= 4 &&
                       (me.tdL / Math.max(1, me.tdA)) >= 0.25 &&
                       (him.tdAgL / Math.max(1, him.tdAgA)) >= 0.30;
        if (!canGet) continue;
      }
      const pc = Math.round(r*100), np = Math.round(norm.med*100);
      const o = OFF[i];
      // `lands` against the defensive `concedes` — the verb says which side of the
      // exchange this is, so neither needs the name to disambiguate it.
      cands.push({ dom: 'strike', w: Math.abs(z) * 0.9,   // slightly behind defense at equal z
        who: LM, lane: i, kind: 'off',
        pred: (z > 0 ? o.hi : o.lo) + ' (lands ' + pc + '% of ' + o.what + vsn(np) + ')' });
    }
  }

  // STYLE, IN THE TWO PIECES IT ACTUALLY HAS. This replaced an "aims unusually
  // often at X" candidate built on share-of-TOTAL-offense, which produced
  // "Kline aims unusually often at ground strikes: 13% of everything she throws".
  // Nobody AIMS at ground strikes — you throw them because you are on the ground.
  // It was a grappling fact wearing a targeting costume, and the Grappling tab
  // already says it properly with control time and takedowns.
  //
  // The distance lanes had the same disease, better disguised. Measured over 524
  // swept fighters: corr(head-share-of-TOTAL, share of offense at range) = 0.703.
  // Half of "he head-hunts" was really "he stays standing". Using distance offense
  // as the denominator drops that to 0.059 — a targeting choice, independent of how
  // often he's standing.
  //
  //   POSITION  — where the fight happens. Real, and nothing else on the Striking
  //               tab says it. Clinch work in particular appears nowhere else.
  //   TARGETING — what he throws once he's at range. The actual choice.
  const totOf = G => G.cells.reduce((s,c) => s + c[1], 0) || 1;
  for (const g of [0, 1, 2]) {
    for (const [me, LM, nm] of [[A,L1,n1],[B,L2,n2]]) {
      const tot = totOf(me);
      if (tot < 150) continue;
      const r = (me.cells[g*3][1] + me.cells[g*3+1][1] + me.cells[g*3+2][1]) / tot;
      const norm = mhNorm(nm, 'pos', g);
      if (!norm) continue;
      const z = zs(r, norm);
      if (Math.abs(z) < 1.4) continue;
      const pc = Math.round(r*100), np = Math.round(norm.med*100);
      // Ground position is tagged 'grap', not 'strike': "where does the striking
      // happen" is a striking number, but "it happens on the mat" is a fact about
      // the grappling, and it belongs next to control time.
      cands.push({ dom: g === 2 ? 'grap' : 'strike', w: Math.abs(z) * 0.75,
        who: LM, lane: 'pos' + g, kind: 'pos',
        pred: (z > 0 ? POS[g].hi : POS[g].lo) + ' (' + pc + '% of total output' + vsn(np) + ')' });
    }
  }
  for (const [t, tname] of [[0,'head'],[1,'body'],[2,'legs']]) {
    for (const [me, LM, nm] of [[A,L1,n1],[B,L2,n2]]) {
      const dt = me.cells[0][1] + me.cells[1][1] + me.cells[2][1];
      if (dt < 100) continue;               // enough range volume to have a habit at all
      const r = me.cells[t][1] / dt;
      const norm = mhNorm(nm, 'aimD', t);
      if (!norm) continue;
      const z = zs(r, norm);
      if (Math.abs(z) < 1.4) continue;
      const pc = Math.round(r*100), np = Math.round(norm.med*100);
      // "at range" stays in the predicate because the denominator is distance
      // offense, not total — the same number the "What they throw at range" section
      // shows. It used to lead the sentence ("At range, X goes to…"), which made
      // this the one candidate that couldn't share a subject with any other.
      cands.push({ dom: 'strike', w: Math.abs(z) * 0.7,
        who: LM, lane: 'aim' + t, kind: 'aim',
        pred: 'goes to the ' + tname + ' at range ' + pc + '% of the time (' + vsn(np).replace(/^, /, '') + ')' });
    }
  }

  // GRAPPLING, beyond takedown defense and control time — both of which are already
  // above, and both of which go quiet on two strikers. Counts only, gated by the
  // same Poisson test the bars use, so the sentence and the colour agree.
  // THESE THREE SAID "58 TAKEDOWNS TO 2" AND MEANT "36 FIGHTS TO 3".
  //
  // Each was a raw career total run through a raw-count Poisson test, i.e. the
  // confound twice: once in the gate that decided the sentence was worth printing,
  // once in the sentence itself. The gate is now _mhLeadRate, which divides by the
  // fights each total was accumulated over, and the PROSE STATES THE RATE — because
  // a read that clears an exposure-adjusted test and then prints the unadjusted
  // number is citing the evidence it didn't use.
  //
  // "Magny lands 1.6 takedowns a fight" is also just the truer sentence about him:
  // a long career in which he occasionally wrestles. "Magny has landed 58 takedowns"
  // describes a specialist who does not exist.
  //
  // The minimum-count floors stay. They aren't significance — _mhLeadRate handles
  // that — they stop the panel leading with a lopsided rate built on two events.
  //
  // THE UNIT IS PER 15 MINUTES, which is what the fighter's own profile page says.
  // These sentences used to be per FIGHT, and a reader who opened Perez's profile
  // right after reading this panel saw 2.07 in one place and 0.9 in the other for
  // the same man — two true numbers that looked like a contradiction, because a
  // fight is not 15 minutes and Perez's average 6.9.
  const rp15 = _mhPer15Bout(A, B);
  const xA = _mhExpOf(A, rp15), xB = _mhExpOf(B, rp15);
  const per = (v, e) => (e ? v/e : 0).toFixed(1);
  const clock = rp15 ? ' per 15 minutes' : ' a fight';
  if (_mhLeadRate(A.tdL, xA, B.tdL, xB) && (A.tdL >= 5 || B.tdL >= 5)) {
    const aHi = _mhRate(A.tdL, xA) > _mhRate(B.tdL, xB);
    const hiN = aHi ? A : B, loN = aHi ? B : A, hiE = aHi ? xA : xB, loE = aHi ? xB : xA;
    cands.push({ dom: 'grap', w: 1.3,
      t: (aHi ? L1 : L2) + ' lands ' + per(hiN.tdL, hiE) + ' takedowns' + clock + ' to ' +
         (aHi ? L2 : L1) + "'s " + per(loN.tdL, loE) + '.' });
  }
  if (_mhLeadRate(A.sub, xA, B.sub, xB) && (A.sub >= 3 || B.sub >= 3)) {
    const aHi = _mhRate(A.sub, xA) > _mhRate(B.sub, xB);
    const hiN = aHi ? A : B, loN = aHi ? B : A, hiE = aHi ? xA : xB, loE = aHi ? xB : xA;
    cands.push({ dom: 'grap', w: 1.2,
      t: (aHi ? L1 : L2) + ' hunts for submissions more often: ' + per(hiN.sub, hiE) +
         ' attempts' + clock + ' to ' + (aHi ? L2 : L1) + "'s " + per(loN.sub, loE) + '.' });
  }
  if (_mhLeadRate(A.kd, xA, B.kd, xB) && (A.kd >= 3 || B.kd >= 3)) {
    const aHi = _mhRate(A.kd, xA) > _mhRate(B.kd, xB);
    const hiN = aHi ? A : B, loN = aHi ? B : A, hiE = aHi ? xA : xB, loE = aHi ? xB : xA;
    cands.push({ dom: 'strike', w: 1.35,
      t: (aHi ? L1 : L2) + ' drops people more often: ' + per(hiN.kd, hiE) +
         ' knockdowns' + clock + ' to ' + (aHi ? L2 : L1) + "'s " + per(loN.kd, loE) + '.' });
  }

  const pool = domain ? cands.filter(c => c.dom === domain) : cands;
  if (!pool.length) return '';
  pool.sort((x,y) => y.w - x.w);
  // Two findings maximum. A third is a paragraph, and a paragraph is a table with
  // extra steps.
  return _ddJoin(pool.slice(0, 2));
}

// TWO FINDINGS, ONE THOUGHT.
//
// The read used to be two finished sentences bolted together with a space, and it
// showed:
//   "Makhachev protects the body well: only 45% of body shots aimed at Makhachev
//    land, vs a 64% norm. Makhachev is accurate to the body: 82% of body shots
//    land, vs a 67% norm."
// Three mentions of one surname, two identical "vs an N% norm" tails, and no
// connective — the two halves of one idea filed as separate paragraphs. Reported
// as "robotic and repetitive", which it was: the structure said these facts have
// nothing to do with each other, and they were about the same man and the same
// body shots.
//
// Measured over the card: of 68 two-finding reads, 42 name the SAME fighter twice
// and 26 name two different men. So the subject is shared more often than not, and
// the join is worth doing properly rather than special-casing the one bout that
// prompted it.
//
//   same man  -> state him once, join the predicates with "and"
//   two men   -> "while", which is a contrast and reads as comparison, not as a list
//
// Candidates with a bare `t` (the grappling comparisons — "X is far harder to take
// down: 44 of 49 stopped, against 8 of 23 for Y") are ALREADY one cohesive
// two-fighter sentence and have no single subject to share. They fall through to
// the old behaviour, which is correct for them.
function _ddJoin(top){
  const say = c => c.t || (c.who + ' ' + c.pred + '.');
  if (!top.length) return '';
  if (top.length === 1) return say(top[0]);
  const [a, b] = top;
  if (a.who && b.who && a.pred && b.pred) {
    if (a.who === b.who) return a.who + ' ' + a.pred + ', and ' + b.pred + '.';
    // "WHILE" IS A CONTRAST, SO IT HAS TO BE EARNED. Measured over the card, 3 of
    // 21 two-man reads put the SAME finding on both men — "Wells throws more
    // ground-and-pound than most, while Orolbai throws more ground-and-pound than
    // most" — where the conjunction promises an opposition and the sentence then
    // delivers an agreement. That is the same species as the rest of this file's
    // history: language outrunning what the numbers say. When both men land the
    // same phrase it is "and", and the two figures sit side by side where a reader
    // can compare them, which is the actual finding.
    // The predicate is repeated in full rather than elided to "and so is McMillen
    // (49%)". Two reasons, and the second is the load-bearing one:
    //   * the elision needs the auxiliary to agree with the verb — "so IS accurate",
    //     "so DOES throw" — and the phrases here start with is/throws/protects/goes/
    //     lands/gets/stays, so it is a conjugation table waiting to print "and so is
    //     Orolbai throws more ground-and-pound";
    //   * the audits match on the full phrase. Eliding it would leave the second
    //     claim of every one of these reads UNCHECKED, silently — which is exactly
    //     how three of the checks in this suite went green while testing nothing.
    // The repetition is also the finding: both men are accurate at range, and the
    // two figures sit side by side where a reader can compare them.
    const phrase = (p) => p.split(' (')[0];
    const conj = phrase(a.pred) === phrase(b.pred) ? ', and ' : ', while ';
    return a.who + ' ' + a.pred + conj + b.who + ' ' + b.pred + '.';
  }
  return say(a) + ' ' + say(b);
}


// _gridNorm (defined in the hub slice above) exists now — build the real,
// normalized GRID_NAMES Set from the raw manifest names baked above. Same
// order of operations as gen-matchup-free.cjs, which does this assignment
// AFTER vm.runInContext(hubJS, ctx) for the exact same reason.
window.GRID_NAMES = new Set(GRID_NAMES_RAW.map(_gridNorm));

// ── entry points for worker/index.js ─────────────────────────────────────
function renderFilter(nameA, nameB, filter) {
  const wantResult = filter === 'all' ? undefined : filter;
  const A = _ddGrid(nameA, wantResult), B = _ddGrid(nameB, wantResult);
  if (!A || !B) return null;
  const rf = filter === 'win' ? 'wins' : filter === 'loss' ? 'losses' : null;
  if (A.noData && B.noData) {
    const empty = '<div class="mh-empty">Neither fighter has any UFC ' + rf + ' on record.</div>';
    return { striking: empty, grappling: empty };
  }
  let note = '';
  if (A.noData || B.noData) {
    const emptyName = A.noData ? nameA : nameB, shownName = A.noData ? nameB : nameA;
    note = '<div class="mh-filter-note">' + escHtmlAttr(emptyName) + ' has no UFC ' + rf +
      ' on record — showing ' + escHtmlAttr(shownName) + '\'s numbers only.</div>';
  }
  return { striking: note + mhStriking(A, B, nameA, nameB), grappling: note + mhGrappling(A, B, nameA, nameB) };
}

// ── raw grid + shading for the app's share-sheet canvas ──────────────────
// mhStriking/mhGrappling above return HTML with the shading already baked in
// as inline style attributes (mhGrid()'s own green/red backgrounds) -- fine
// for a DOM the client renders, useless for a <canvas> the client draws
// itself (see mobile/www/js/gl-sheet.js's drawStriking/drawGrappling, ported
// from GL_SHEET in index.html but fed real numbers over the wire instead of
// reading FIGHT_GRID/FIGHT_STATS globals the app never loads). Recomputes
// the SAME verdicts mhGrid()/_mhGrade() already compute for the HTML path,
// just returned as plain numbers/strings instead of baked into a style
// attribute or a coloured <div> -- same floor (_MH_FLOOR), same median/
// spread lookup (mhNorm), same two-bar grade test (_mhGrade), so a share
// sheet can never show a shade the modal itself would disagree with.
const SHEET_LANES = [['dist','head'],['dist','body'],['dist','leg'],['ground','head']];
function sheetSide(name) {
  const G = _ddGrid(name, undefined);
  if (!G) return null;
  const shadeCells = [], shadeCellsD = [];
  for (let i = 0; i < 9; i++) {
    const acc = G.cells[i], def = G.cellsD[i];
    const an = acc[1], dn = def[1];
    const ar = an ? acc[0]/an : 0, dr = dn ? def[0]/dn : 0;
    const ab = an >= _MH_FLOOR ? mhNorm(name, 'acc', i) : null;
    const db = dn >= _MH_FLOOR ? mhNorm(name, 'allow', i) : null;
    shadeCells.push(ab ? Math.max(-1, Math.min(1, ((ar - ab.med) / ab.spread) / 2)) : null);
    // Inverted, same as mhGrid()'s own `if (invert) z = -z` for cellsD --
    // getting hit less than your peers is the good end, so the sign flips.
    shadeCellsD.push(db ? -Math.max(-1, Math.min(1, ((dr - db.med) / db.spread) / 2)) : null);
  }
  const gradeAllow = SHEET_LANES.map(([p, t]) => {
    const i = _MH_GI(p, t), cell = G.cellsD[i], n = cell[1];
    if (n < _MH_FLOOR) return null;
    const r = cell[0] / n;
    return _mhGrade(r, n, mhNorm(name, 'allow', i), true);
  });
  return Object.assign({}, G, { shadeCells, shadeCellsD, gradeAllow });
}
function sheetGrid(nameA, nameB) {
  const A = sheetSide(nameA), B = sheetSide(nameB);
  return (A && B) ? { A, B } : null;
}

// Cheap per-fighter-pair check — two Set lookups through the same
// alias-normalizing glHasGrid() the hub itself gates on (see index.html's
// own comment: raw-string joins on this have broken three times already).
// Used by worker/index.js to annotate /api/app/matchup fights with a `dd`
// boolean, so the app only ever shows a Deep Dive button for a pairing
// that actually has data, never a dead-end tap.
export function deepDiveAvailable(f1, f2) {
  return glDeepDiveAvailable(f1, f2);
}
// The full modal payload for an arbitrary pair, computed live. Returns
// null when the pairing has no grid data (a debut, or a sweep that hasn't
// reached one of them) — not an error, same convention as fight-sim.js's
// runFightSim() returning null for an unresolvable name.
export async function computeDeepDive(env, nameA, nameB) {
  if (!glDeepDiveAvailable(nameA, nameB)) return null;
  await _ensureDeepDiveHistory(env);
  const striking = {}, grappling = {};
  for (const filter of ['all', 'win', 'loss']) {
    const r = renderFilter(nameA, nameB, filter);
    if (!r) return null;
    striking[filter] = r.striking;
    grappling[filter] = r.grappling;
  }
  return { n1: nameA, n2: nameB, striking, grappling, sheet: sheetGrid(nameA, nameB) };
}
